<script>
(() => {
  const app = document.getElementById('app');
  const taskList = document.getElementById('taskList');
  const clock = document.getElementById('clock');
  const startButton = document.getElementById('startButton');
  const skipButton = document.getElementById('skipButton');
  const toast = document.getElementById('toast');
  const summary = document.getElementById('summary');
  const menuPop = document.getElementById('menuPop');
  let mode = 'pomodoro', seconds = 1500, running = false, interval = null, tasks = [], editorOpen = false;

  const durations = {pomodoro:1500, short:300, long:900};
  const captions = {pomodoro:'Time to focus!', short:'Time for a break!', long:'Time for a break!'};

  function formatTime(value) {
    const m = Math.floor(value / 60), s = value % 60;
    return String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');
  }
  function setMode(next) {
    mode = next;
    document.body.style.setProperty('--bg', next === 'short' ? '#80595f' : next === 'long' ? '#38868a' : '#ad3849');
    document.body.style.setProperty('--accent', next === 'short' ? '#80595f' : next === 'long' ? '#38868a' : '#ad3849');
    document.querySelectorAll('.mode').forEach(b => b.classList.toggle('active', b.dataset.mode === next));
    seconds = durations[next];
    clock.textContent = formatTime(seconds);
    document.getElementById('caption').textContent = captions[next];
    stopTimer();
  }
  document.querySelectorAll('.mode').forEach(b => b.addEventListener('click', () => setMode(b.dataset.mode)));

  function stopTimer() {
    running = false;
    clearInterval(interval);
    interval = null;
    startButton.textContent = 'START';
    skipButton.style.display = 'none';
  }
  function startTimer() {
    if (running) {
      stopTimer();
      return;
    }
    running = true;
    startButton.textContent = 'PAUSE';
    skipButton.style.display = 'block';
    interval = setInterval(() => {
      if (seconds > 0) {
        seconds--;
        clock.textContent = formatTime(seconds);
      } else {
        stopTimer();
        setMode(mode === 'pomodoro' ? 'short' : 'pomodoro');
      }
    }, 1000);
  }
  startButton.addEventListener('click', startTimer);
  skipButton.addEventListener('click', () => {
    stopTimer();
    setMode(mode === 'pomodoro' ? 'short' : 'pomodoro');
  });

  function editorMarkup() {
    return `<div class="task-editor">
      <div class="editor-main">
        <input class="task-title" type="text" placeholder="What are you working on?" aria-label="Task name">
        <div class="estimate-label">Est Pomodoros</div>
        <div class="estimate-controls">
          <input class="estimate-value" type="number" min="1" value="1" aria-label="Estimated pomodoros">
          <button class="stepper btn up" aria-label="Increase estimate">▲</button>
          <button class="stepper btn down" aria-label="Decrease estimate">▼</button>
        </div>
        <div class="editor-links">
          <button class="btn note-link">+ Add Note</button>
          <button class="btn project-link">+ Add Project</button><span class="lock">🔒</span>
        </div>
      </div>
      <div class="editor-footer">
        <button class="cancel btn">Cancel</button>
        <button class="save btn">Save</button>
      </div>
    </div>`;
  }

  function render() {
    taskList.innerHTML = '';
    tasks.forEach((task, index) => {
      const row = document.createElement('div');
      row.className = 'task-row' + (task.done ? ' done' : '');
      row.innerHTML = `<button class="task-check btn" aria-label="Complete task">${task.done ? '✓' : '✓'}</button>
        <span class="task-name"></span><span class="task-count">${task.done ? task.estimate : 0} / ${task.estimate}</span>
        <button class="icon-button row-menu btn" aria-label="Task options"><span class="dots">⋮</span></button>`;
      row.querySelector('.task-name').textContent = task.name;
      row.querySelector('.task-check').addEventListener('click', () => toggleTask(index));
      row.querySelector('.row-menu').addEventListener('click', () => {
        task.name = task.name;
        openEditor(index);
      });
      taskList.appendChild(row);
    });

    if (editorOpen) {
      const wrapper = document.createElement('div');
      wrapper.innerHTML = editorMarkup();
      const editor = wrapper.firstElementChild;
      taskList.appendChild(editor);
      const title = editor.querySelector('.task-title');
      const estimate = editor.querySelector('.estimate-value');
      const editing = app.dataset.editing;
      if (editing !== undefined && editing !== '') {
        const item = tasks[Number(editing)];
        if (item) { title.value = item.name; estimate.value = item.estimate; }
      }
      editor.querySelector('.up').addEventListener('click', () => estimate.value = Math.max(1, Number(estimate.value || 1) + 1));
      editor.querySelector('.down').addEventListener('click', () => estimate.value = Math.max(1, Number(estimate.value || 1) - 1));
      editor.querySelector('.cancel').addEventListener('click', () => {
        editorOpen = false; app.dataset.editing = ''; render();
      });
      editor.querySelector('.save').addEventListener('click', () => {
        const name = title.value.trim();
        if (!name) { title.focus(); return; }
        const e = Math.max(1, Number(estimate.value) || 1);
        if (app.dataset.editing !== '') {
          const idx = Number(app.dataset.editing);
          tasks[idx] = {...tasks[idx], name, estimate:e};
          app.dataset.editing = '';
        } else {
          tasks.push({name, estimate:e, done:false});
        }
        editorOpen = true;
        updateTaskInfo();
        render();
      });
    } else if (!tasks.length) {
      const add = document.createElement('button');
      add.className = 'add-task btn';
      add.innerHTML = '<span class="plus-circle">+</span>Add Task';
      add.addEventListener('click', () => openEditor());
      taskList.appendChild(add);
    } else {
      const add = document.createElement('button');
      add.className = 'add-task btn';
      add.innerHTML = '<span class="plus-circle">+</span>Add Task';
      add.addEventListener('click', () => openEditor());
      taskList.appendChild(add);
    }
    app.classList.toggle('editor-open', editorOpen);
    app.classList.toggle('has-tasks', tasks.length > 0);
    if (tasks.length) {
      summary.style.display = 'flex';
      const total = tasks.reduce((n,t) => n + (t.done ? 0 : t.estimate), 0);
      const done = tasks.reduce((n,t) => n + (t.done ? t.estimate : 0), 0);
      document.getElementById('summaryDone').textContent = done;
      document.getElementById('summaryTotal').textContent = total;
      document.getElementById('finishHours').textContent = total ? `(${(total * .4).toFixed(1)}h)` : '(0h)';
    } else summary.style.display = 'none';
  }

  function openEditor(index) {
    editorOpen = true;
    app.dataset.editing = index === undefined ? '' : String(index);
    render();
    if (window.scrollY < 100) {
      setTimeout(() => {
        const editor = document.querySelector('.task-editor');
        if (editor) window.scrollTo(0, Math.max(0, editor.getBoundingClientRect().top + window.scrollY - 227));
      }, 40);
    }
    setTimeout(() => document.querySelector('.task-title')?.focus(), 60);
  }
  function updateTaskInfo() {
    const active = tasks.find(t => !t.done);
    document.getElementById('sessionTask').textContent = active ? active.name : '';
    document.getElementById('caption').textContent = active ? captions[mode] : (tasks.length ? captions[mode] : captions[mode]);
  }
  function toggleTask(index) {
    tasks[index].done = !tasks[index].done;
    if (tasks.every(t => t.done)) {
      stopTimer();
      seconds = durations.pomodoro;
      clock.textContent = formatTime(seconds);
      mode = 'pomodoro';
      document.body.style.setProperty('--bg', '#ad3849');
      document.body.style.setProperty('--accent', '#ad3849');
      document.querySelectorAll('.mode').forEach(b => b.classList.toggle('active', b.dataset.mode === 'pomodoro'));
      document.getElementById('caption').textContent = 'Time to focus!';
      document.getElementById('sessionTask').textContent = '';
      toast.classList.add('show');
      makeConfetti();
    } else updateTaskInfo();
    render();
  }
  function makeConfetti() {
    const layer = document.getElementById('confetti');
    layer.innerHTML = '';
    const colors = ['#ffcf47','#47b6ee','#f26e8c','#9e24cb','#52da94','#fff'];
    for (let i = 0; i < 72; i++) {
      const piece = document.createElement('i');
      piece.style.left = Math.random() * 100 + '%';
      piece.style.top = (Math.random() * 50 - 15) + '%';
      piece.style.background = colors[i % colors.length];
      piece.style.animationDelay = (Math.random() * .8) + 's';
      layer.appendChild(piece);
    }
    setTimeout(() => layer.innerHTML = '', 3500);
  }

  document.getElementById('taskMenu').addEventListener('click', e => {
    const r = e.currentTarget.getBoundingClientRect();
    menuPop.style.left = Math.max(10, r.left - 140) + 'px';
    menuPop.style.top = (r.bottom + window.scrollY + 5) + 'px';
    menuPop.classList.toggle('show');
  });
  document.getElementById('headerMenu').addEventListener('click', () => menuPop.classList.toggle('show'));
  document.getElementById('clearFinished').addEventListener('click', () => {
    tasks = tasks.filter(t => !t.done); menuPop.classList.remove('show'); toast.classList.remove('show'); editorOpen = false; render();
  });
  document.getElementById('clearAll').addEventListener('click', () => {
    tasks = []; editorOpen = false; menuPop.classList.remove('show'); toast.classList.remove('show'); render();
  });
  document.getElementById('addFromMenu').addEventListener('click', () => { menuPop.classList.remove('show'); openEditor(); });
  document.getElementById('clearTasks').addEventListener('click', () => {
    tasks = []; editorOpen = false; toast.classList.remove('show'); render();
  });

  render();
})();
</script>
